// =======================================================
// JavaScript MasterClass • Exercício 1 (Rodrigo Branas)
// =======================================================

console.log("Inicio 🚀");

// 1. Comando SQL DDL fornecido:
const statement = "Create table author (id number, name string, age number, city string, state string, country string)";

// 2. RegExp com Grupos de Captura:
//    - Grupo 1: ([a-z]+) -> Nome da tabela
//    - Grupo 2: (.+)     -> Colunas entre os parênteses \( e \)
const regexp = /Create table ([a-z]+) \((.+)\)/;

// 3. Execução do casamento com match:
const parseStatement = statement.match(regexp);

console.log("parseStatement:", parseStatement);
console.log("======================");

// 4. Extração para variáveis individuais:
const tableName = parseStatement ? parseStatement[1] : "";
let columns = parseStatement ? parseStatement[2] : "";

console.log("tableName:", tableName);
console.log("columns (bruta):", columns);
console.log("======================");

// 5. Separação das colunas em array:
columns = columns.split(", ");

console.log("columns (array):", columns);

// -------------------------------------------------------
// Validação do Exercício:
// -------------------------------------------------------
console.log("\n=== VALIDAÇÃO DO DESAFIO ===");
const isTableValid = tableName === "author";
const isColumnsValid = Array.isArray(columns) && columns.length === 6;

console.log("1. tableName correto:", isTableValid ? "✅ PASSOU ('author')" : "❌ FALHOU");
console.log("2. columns em array:", isColumnsValid ? `✅ PASSOU (${columns.length} colunas)` : "❌ FALHOU");

if (isTableValid && isColumnsValid) {
  console.log("\n🎉 Parabéns! Exercício 1 resolvido com sucesso!");
}
